const days = Number($('실습 설정').first().json.reportDays) || 0;
const cutoff = days > 0 ? Date.now() - days * 24 * 60 * 60 * 1000 : null;

const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => {
    if (!cutoff) return true;
    const ts = new Date(row['타임스탬프']).getTime();
    return !Number.isNaN(ts) && ts >= cutoff;
  });

const total = rows.length;

const avg = (key) => {
  const nums = rows.map((r) => Number(r[key])).filter((n) => !Number.isNaN(n));
  if (nums.length === 0) return 0;
  return Math.round((nums.reduce((a, b) => a + b, 0) / nums.length) * 10) / 10;
};

const countBy = (key) => {
  const counts = {};
  for (const r of rows) {
    const v = r[key] || '미응답';
    counts[v] = (counts[v] || 0) + 1;
  }
  return Object.entries(counts).map(([name, count]) => ({
    name,
    count,
    percent: total > 0 ? Math.round((count / total) * 1000) / 10 : 0,
  }));
};

const opinions = rows
  .map((r) => (r['개선이 필요한 사항'] || '').trim())
  .filter((s) => s.length > 0);

return [{
  json: {
    totalCount: total,
    avgOverall: avg('전체 만족도'),
    avgSpeed: avg('처리 속도 만족도'),
    avgKindness: avg('직원 친절도'),
    avgRevisit: avg('다시 이용할 의향'),
    byAge: countBy('연령대'),
    byService: countBy('이용한 행정 서비스'),
    opinions,
    opinionCount: opinions.length,
  },
}];

const stats = $('통계 집계').first().json;
const setup = $('실습 설정').first().json;
const aiHtml = $json.text;

const days = Number(setup.reportDays) || 0;
const periodLabel = days === 0 ? '전체 기간' : `최근 ${days}일`;

const now = new Date(Date.now() + 9 * 60 * 60 * 1000);
const pad2 = (n) => String(n).padStart(2, '0');
const generatedAt = `${now.getUTCFullYear()}-${pad2(now.getUTCMonth() + 1)}-${pad2(now.getUTCDate())} ${pad2(now.getUTCHours())}:${pad2(now.getUTCMinutes())}`;

const tableRows = (list) => list.map((row) =>
  `<tr><td style="padding:6px 10px;border:1px solid #ddd;">${row.name}</td>` +
  `<td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${row.count}건</td>` +
  `<td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${row.percent}%</td></tr>`
).join('');

const tableHead =
  '<tr><th style="padding:6px 10px;border:1px solid #ddd;background:#f4f6f9;">구분</th>' +
  '<th style="padding:6px 10px;border:1px solid #ddd;background:#f4f6f9;">응답 수</th>' +
  '<th style="padding:6px 10px;border:1px solid #ddd;background:#f4f6f9;">비율</th></tr>';

const emailHtml = `
<div style="font-family:'Malgun Gothic',sans-serif;max-width:640px;margin:0 auto;color:#222;line-height:1.7;">
  <h2 style="border-bottom:2px solid #ea4b71;padding-bottom:8px;">${setup.reportTitle}</h2>
  <p style="color:#666;font-size:13px;">분석 기간: ${periodLabel} · 보고서 생성 시각: ${generatedAt}</p>

  <h3>핵심 지표</h3>
  <table style="border-collapse:collapse;width:100%;">
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">총 응답자 수</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.totalCount}명</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">전체 만족도</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.avgOverall} / 5</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">처리 속도 만족도</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.avgSpeed} / 5</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">직원 친절도</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.avgKindness} / 5</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">다시 이용할 의향</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.avgRevisit} / 5</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #ddd;">서술형 의견 수</td><td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${stats.opinionCount}건</td></tr>
  </table>

  <h3>서비스 이용 분포</h3>
  <table style="border-collapse:collapse;width:100%;">${tableHead}${tableRows(stats.byService)}</table>

  <h3>연령대 분포</h3>
  <table style="border-collapse:collapse;width:100%;">${tableHead}${tableRows(stats.byAge)}</table>

  <h3>AI 분석</h3>
  ${aiHtml}
</div>
`;

const subject = `[${setup.reportTitle}] ${periodLabel} 결과 (${generatedAt.slice(0, 10)})`;

return [{ json: { emailHtml, subject } }];
